HTML_CONTENT = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no" />\n  <title>🏎️ Terminal Racing - Extreme Combat Edition</title>\n  <meta name="description" content="Play Terminal Racing in your browser! High-octane ASCII arcade combat racing featuring weaponized hypercars, twin plasma shooters, turbo nitro, and dynamic particle FX." />\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700;900&family=Share+Tech+Mono&family=Inter:wght@400;600&display=swap" rel="stylesheet">\n  <style>\n    :root {\n      --bg-space: #06070c;\n      --bg-panel: #0d111a;\n      --neon-cyan: #00f0ff;\n      --neon-pink: #ff0055;\n      --neon-yellow: #ffe600;\n      --neon-green: #00ff66;\n      --neon-purple: #9d00ff;\n      --text-dim: #7d889b;\n      --text-main: #e2e8f0;\n      --crt-glow: rgba(0, 240, 255, 0.25);\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      user-select: none;\n      -webkit-user-select: none;\n    }\n\n    body {\n      background-color: var(--bg-space);\n      background-image: \n        radial-gradient(circle at 50% 20%, rgba(0, 240, 255, 0.08) 0%, transparent 60%),\n        radial-gradient(circle at 80% 80%, rgba(255, 0, 85, 0.05) 0%, transparent 50%);\n      color: var(--text-main);\n      font-family: \'Share Tech Mono\', monospace;\n      min-height: 100vh;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: space-between;\n      overflow-x: hidden;\n      padding: 10px;\n    }\n\n    /* Top Navigation Header */\n    header {\n      width: 100%;\n      max-width: 900px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 8px 16px;\n      margin-bottom: 6px;\n      background: rgba(13, 17, 26, 0.85);\n      backdrop-filter: blur(10px);\n      border: 1px solid rgba(0, 240, 255, 0.2);\n      border-radius: 12px;\n      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);\n    }\n\n    .brand-title {\n      font-family: \'Orbitron\', sans-serif;\n      font-weight: 900;\n      font-size: 1.25rem;\n      letter-spacing: 2px;\n      color: var(--neon-cyan);\n      text-shadow: 0 0 10px rgba(0, 240, 255, 0.6);\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .header-actions {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    .btn-header {\n      background: rgba(0, 240, 255, 0.1);\n      border: 1px solid var(--neon-cyan);\n      color: var(--neon-cyan);\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 0.75rem;\n      padding: 6px 12px;\n      border-radius: 6px;\n      cursor: pointer;\n      transition: all 0.2s ease;\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      text-decoration: none;\n    }\n\n    .btn-header:hover {\n      background: var(--neon-cyan);\n      color: var(--bg-space);\n      box-shadow: 0 0 12px var(--neon-cyan);\n    }\n\n    /* Game Viewport Container */\n    #arcade-container {\n      position: relative;\n      width: 100%;\n      max-width: 720px;\n      aspect-ratio: 9 / 13;\n      max-height: 82vh;\n      background: #000;\n      border-radius: 14px;\n      overflow: hidden;\n      box-shadow: \n        0 0 0 2px rgba(0, 240, 255, 0.3),\n        0 0 35px rgba(0, 240, 255, 0.25),\n        0 20px 50px rgba(0,0,0,0.8);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n\n    canvas#gameCanvas {\n      width: 100%;\n      height: 100%;\n      display: block;\n      image-rendering: pixelated;\n      background: #05070a;\n    }\n\n    /* CRT Scanline Overlay */\n    .crt-overlay {\n      position: absolute;\n      inset: 0;\n      pointer-events: none;\n      background: linear-gradient(\n        rgba(18, 16, 16, 0) 50%, \n        rgba(0, 0, 0, 0.35) 50%\n      ), linear-gradient(\n        90deg,\n        rgba(255, 0, 0, 0.03),\n        rgba(0, 255, 0, 0.01),\n        rgba(0, 0, 255, 0.03)\n      );\n      background-size: 100% 4px, 6px 100%;\n      opacity: 0.65;\n      transition: opacity 0.3s;\n    }\n\n    .crt-vignette {\n      position: absolute;\n      inset: 0;\n      pointer-events: none;\n      box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.85);\n      border-radius: 14px;\n    }\n\n    /* Overlays: Start Screen & Game Over Screen */\n    .screen-overlay {\n      position: absolute;\n      inset: 0;\n      background: rgba(5, 7, 12, 0.88);\n      backdrop-filter: blur(4px);\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      padding: 24px;\n      text-align: center;\n      z-index: 10;\n      transition: opacity 0.25s ease;\n    }\n\n    .screen-overlay.hidden {\n      display: none;\n      opacity: 0;\n    }\n\n    .overlay-title {\n      font-family: \'Orbitron\', sans-serif;\n      font-size: clamp(1.6rem, 5vw, 2.4rem);\n      font-weight: 900;\n      color: var(--neon-cyan);\n      text-shadow: 0 0 15px rgba(0, 240, 255, 0.8);\n      margin-bottom: 8px;\n    }\n\n    .overlay-subtitle {\n      font-family: \'Orbitron\', sans-serif;\n      color: var(--neon-pink);\n      letter-spacing: 3px;\n      font-size: 0.9rem;\n      margin-bottom: 24px;\n      text-transform: uppercase;\n    }\n\n    .overlay-card {\n      background: rgba(13, 17, 26, 0.9);\n      border: 1px solid rgba(0, 240, 255, 0.3);\n      border-radius: 12px;\n      padding: 16px 20px;\n      width: 100%;\n      max-width: 440px;\n      margin-bottom: 20px;\n      box-shadow: 0 4px 20px rgba(0, 0, 0, 0.6);\n    }\n\n    .car-preview-box {\n      font-size: 1.4rem;\n      line-height: 1.15;\n      color: var(--neon-cyan);\n      margin: 12px 0;\n      background: rgba(0, 0, 0, 0.5);\n      padding: 10px;\n      border-radius: 8px;\n      border: 1px dashed rgba(0, 240, 255, 0.3);\n      font-weight: bold;\n    }\n\n    .car-specs {\n      display: flex;\n      justify-content: space-around;\n      margin-top: 10px;\n      font-size: 0.8rem;\n      color: var(--neon-yellow);\n    }\n\n    .btn-action {\n      background: linear-gradient(135deg, var(--neon-cyan), #0070f3);\n      color: #000;\n      font-family: \'Orbitron\', sans-serif;\n      font-weight: 900;\n      font-size: 1.1rem;\n      padding: 14px 34px;\n      border: none;\n      border-radius: 8px;\n      cursor: pointer;\n      box-shadow: 0 0 20px rgba(0, 240, 255, 0.6);\n      transition: all 0.2s ease;\n      letter-spacing: 1px;\n    }\n\n    .btn-action:hover {\n      transform: scale(1.05);\n      box-shadow: 0 0 30px rgba(0, 240, 255, 0.9);\n    }\n\n    .control-legend {\n      display: grid;\n      grid-template-columns: 1fr 1fr;\n      gap: 8px;\n      font-size: 0.78rem;\n      color: var(--text-dim);\n      margin-top: 14px;\n      text-align: left;\n    }\n\n    .control-legend span {\n      color: var(--text-main);\n      font-weight: bold;\n    }\n\n    /* Mobile Controls Bar */\n    #mobile-controls {\n      display: none;\n      width: 100%;\n      max-width: 720px;\n      margin-top: 10px;\n      gap: 8px;\n      justify-content: space-between;\n    }\n\n    @media (max-width: 768px) {\n      #mobile-controls {\n        display: flex;\n      }\n      #arcade-container {\n        max-height: 68vh;\n      }\n    }\n\n    .touch-btn {\n      flex: 1;\n      padding: 14px 8px;\n      background: rgba(13, 17, 26, 0.95);\n      border: 1px solid rgba(0, 240, 255, 0.35);\n      border-radius: 10px;\n      color: var(--neon-cyan);\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 0.9rem;\n      font-weight: bold;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      gap: 4px;\n      touch-action: manipulation;\n      transition: background 0.1s, transform 0.1s;\n    }\n\n    .touch-btn:active {\n      background: var(--neon-cyan);\n      color: #000;\n      transform: scale(0.96);\n    }\n\n    .touch-btn.shoot-btn {\n      border-color: var(--neon-pink);\n      color: var(--neon-pink);\n    }\n    .touch-btn.shoot-btn:active {\n      background: var(--neon-pink);\n      color: #fff;\n    }\n\n    .touch-btn.boost-btn {\n      border-color: var(--neon-yellow);\n      color: var(--neon-yellow);\n    }\n    .touch-btn.boost-btn:active {\n      background: var(--neon-yellow);\n      color: #000;\n    }\n\n    /* Footer with quick Docker details */\n    footer {\n      width: 100%;\n      max-width: 900px;\n      display: flex;\n      justify-content: space-between;\n      align-items: center;\n      padding: 8px 16px;\n      margin-top: 8px;\n      font-size: 0.75rem;\n      color: var(--text-dim);\n    }\n\n    .docker-snippet {\n      background: rgba(0, 0, 0, 0.6);\n      border: 1px solid rgba(0, 240, 255, 0.2);\n      padding: 4px 10px;\n      border-radius: 6px;\n      color: var(--neon-green);\n      font-family: monospace;\n      cursor: pointer;\n    }\n\n    .docker-snippet:hover {\n      border-color: var(--neon-green);\n    }\n  </style>\n</head>\n<body>\n\n  <!-- Top Bar -->\n  <header>\n    <div class="brand-title">\n      <span>🏎️</span> TERMINAL RACING\n    </div>\n    <div class="header-actions">\n      <button id="toggleAudioBtn" class="btn-header">🔊 AUDIO: ON</button>\n      <button id="toggleCrtBtn" class="btn-header">📺 CRT: ON</button>\n      <a href="https://github.com/Visakan2004/terminal-racing" target="_blank" class="btn-header">⚡ GITHUB</a>\n    </div>\n  </header>\n\n  <!-- Arcade Machine Game Container -->\n  <div id="arcade-container">\n    <canvas id="gameCanvas" width="480" height="640"></canvas>\n    \n    <div id="crtOverlay" class="crt-overlay"></div>\n    <div class="crt-vignette"></div>\n\n    <!-- Start Overlay Screen -->\n    <div id="startScreen" class="screen-overlay">\n      <h1 class="overlay-title">TERMINAL RACING</h1>\n      <p class="overlay-subtitle">EXTREME COMBAT EDITION</p>\n\n      <div class="overlay-card">\n        <div style="display:flex; justify-content:space-between; align-items:center;">\n          <span style="color:var(--text-dim);">SELECT CHASSIS:</span>\n          <button id="changeCarBtn" class="btn-header" style="font-size:0.7rem;">SWITCH [C]</button>\n        </div>\n        \n        <div id="carPreviewName" style="font-family:\'Orbitron\'; font-size:0.95rem; color:var(--neon-yellow); margin-top:8px;">\n          ⚡ APEX V12 RAILGUN\n        </div>\n\n        <pre id="carPreviewArt" class="car-preview-box">╓/▲\\╖\n║█▓█║\ndb=db</pre>\n\n        <div class="car-specs">\n          <span id="carWeaponName">WEAPON: TWIN PLASMA</span>\n          <span id="carBulletType">TYPE: LASER BOLT</span>\n        </div>\n      </div>\n\n      <button id="startPlayBtn" class="btn-action">START ENGINE [SPACE]</button>\n\n      <div class="control-legend">\n        <div><span>[← / A] [→ / D]</span> Steer</div>\n        <div><span>[SPACE / J]</span> Fire Cannons</div>\n        <div><span>[↑ / W / SHIFT]</span> Nitro Turbo</div>\n        <div><span>[C]</span> Switch Car</div>\n      </div>\n    </div>\n\n    <!-- Game Over Screen -->\n    <div id="gameOverScreen" class="screen-overlay hidden">\n      <h1 class="overlay-title" style="color:var(--neon-pink); text-shadow:0 0 20px var(--neon-pink);">CRASHED!</h1>\n      <p class="overlay-subtitle">MISSION TERMINATED</p>\n\n      <div class="overlay-card" style="border-color:rgba(255,0,85,0.4);">\n        <div style="display:grid; grid-template-columns: 1fr 1fr; gap:12px; text-align:left; font-size:0.85rem;">\n          <div>SCORE: <span id="finalScore" style="color:var(--neon-cyan); font-weight:bold; font-size:1.1rem;">0</span></div>\n          <div>HIGH SCORE: <span id="finalHighScore" style="color:var(--neon-yellow); font-weight:bold; font-size:1.1rem;">0</span></div>\n          <div>ENEMIES DESTROYED: <span id="finalKills" style="color:var(--neon-pink); font-weight:bold;">0</span></div>\n          <div>NEAR MISSES: <span id="finalPasses" style="color:var(--neon-green); font-weight:bold;">0</span></div>\n        </div>\n      </div>\n\n      <button id="restartBtn" class="btn-action" style="background:linear-gradient(135deg, var(--neon-pink), #9d00ff); color:#fff; box-shadow:0 0 20px rgba(255,0,85,0.6);">\n        RESTART RACE [R]\n      </button>\n    </div>\n  </div>\n\n  <!-- Mobile Controls -->\n  <div id="mobile-controls">\n    <button class="touch-btn" id="mLeftBtn">◀ STEER</button>\n    <button class="touch-btn shoot-btn" id="mShootBtn">💥 FIRE</button>\n    <button class="touch-btn boost-btn" id="mBoostBtn">🔥 NITRO</button>\n    <button class="touch-btn" id="mRightBtn">STEER ▶</button>\n  </div>\n\n  <!-- Footer -->\n  <footer>\n    <span>Docker CLI: <code class="docker-snippet" onclick="navigator.clipboard.writeText(\'docker run -it --rm ghcr.io/visakan2004/terminal-racing:latest\'); alert(\'Copied Docker run command!\');">docker run -it --rm ghcr.io/visakan2004/terminal-racing:latest</code></span>\n    <span>v2.4 ARCADE</span>\n  </footer>\n\n  <!-- Audio Synthesizer & Game Engine Script -->\n  <script>\n    /* =========================================================================\n       1. WEB AUDIO PROCEDURAL SYNTHESIZER\n       ========================================================================= */\n    class SoundFX {\n      constructor() {\n        this.ctx = null;\n        this.enabled = true;\n      }\n\n      init() {\n        if (!this.ctx) {\n          const AudioCtx = window.AudioContext || window.webkitAudioContext;\n          if (AudioCtx) this.ctx = new AudioCtx();\n        }\n        if (this.ctx && this.ctx.state === \'suspended\') {\n          this.ctx.resume();\n        }\n      }\n\n      shoot() {\n        if (!this.enabled || !this.ctx) return;\n        const now = this.ctx.currentTime;\n        const osc = this.ctx.createOscillator();\n        const gain = this.ctx.createGain();\n\n        osc.type = \'sawtooth\';\n        osc.frequency.setValueAtTime(880, now);\n        osc.frequency.exponentialRampToValueAtTime(110, now + 0.12);\n\n        gain.gain.setValueAtTime(0.2, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.12);\n\n        osc.connect(gain);\n        gain.connect(this.ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.12);\n      }\n\n      explosion() {\n        if (!this.enabled || !this.ctx) return;\n        const now = this.ctx.currentTime;\n        const bufferSize = this.ctx.sampleRate * 0.4;\n        const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);\n        const output = buffer.getChannelData(0);\n        for (let i = 0; i < bufferSize; i++) {\n          output[i] = Math.random() * 2 - 1;\n        }\n\n        const whiteNoise = this.ctx.createBufferSource();\n        whiteNoise.buffer = buffer;\n\n        const filter = this.ctx.createBiquadFilter();\n        filter.type = \'lowpass\';\n        filter.frequency.setValueAtTime(800, now);\n        filter.frequency.linearRampToValueAtTime(50, now + 0.4);\n\n        const gain = this.ctx.createGain();\n        gain.gain.setValueAtTime(0.5, now);\n        gain.gain.exponentialRampToValueAtTime(0.01, now + 0.4);\n\n        whiteNoise.connect(filter);\n        filter.connect(gain);\n        gain.connect(this.ctx.destination);\n        whiteNoise.start(now);\n      }\n\n      nitro() {\n        if (!this.enabled || !this.ctx) return;\n        const now = this.ctx.currentTime;\n        const osc = this.ctx.createOscillator();\n        const gain = this.ctx.createGain();\n\n        osc.type = \'sine\';\n        osc.frequency.setValueAtTime(150, now);\n        osc.frequency.exponentialRampToValueAtTime(450, now + 0.18);\n\n        gain.gain.setValueAtTime(0.18, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.18);\n\n        osc.connect(gain);\n        gain.connect(this.ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.18);\n      }\n\n      nearMiss() {\n        if (!this.enabled || !this.ctx) return;\n        const now = this.ctx.currentTime;\n        const osc = this.ctx.createOscillator();\n        const gain = this.ctx.createGain();\n\n        osc.type = \'triangle\';\n        osc.frequency.setValueAtTime(587.33, now); // D5\n        osc.frequency.setValueAtTime(880, now + 0.08); // A5\n\n        gain.gain.setValueAtTime(0.2, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.2);\n\n        osc.connect(gain);\n        gain.connect(this.ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.2);\n      }\n\n      switchCar() {\n        if (!this.enabled || !this.ctx) return;\n        const now = this.ctx.currentTime;\n        const osc = this.ctx.createOscillator();\n        const gain = this.ctx.createGain();\n\n        osc.type = \'square\';\n        osc.frequency.setValueAtTime(440, now);\n        osc.frequency.setValueAtTime(659.25, now + 0.05);\n\n        gain.gain.setValueAtTime(0.15, now);\n        gain.gain.linearRampToValueAtTime(0.01, now + 0.12);\n\n        osc.connect(gain);\n        gain.connect(this.ctx.destination);\n        osc.start(now);\n        osc.stop(now + 0.12);\n      }\n    }\n\n    const sfx = new SoundFX();\n\n    /* =========================================================================\n       2. CAR CHASSIS DATA\n       ========================================================================= */\n    const PLAYER_CARS = [\n      {\n        name: "⚡ APEX V12 RAILGUN",\n        weaponName: "TWIN PLASMA",\n        bulletChar: "║",\n        bulletColor: "#00f0ff",\n        flameColor: "#00f0ff",\n        themeColor: "#00f0ff",\n        sprites: {\n          straight: ["╓/▲\\\\╖", "║█▓█║", "db=db"],\n          left:     ["╓/▲\\\\ ", "\\\\\\\\█▓\\\\\\\\", "db=db"],\n          right:    [" /▲\\\\╖", "//█▓//", "db=db"]\n        }\n      },\n      {\n        name: "🚀 CYBER WARSHIP",\n        weaponName: "EMP LIGHTNING",\n        bulletChar: "⚡",\n        bulletColor: "#00ffea",\n        flameColor: "#ff00ea",\n        themeColor: "#00ffea",\n        sprites: {\n          straight: ["▲/══\\\\▲", "║⚡X⚡║", "d-==-b"],\n          left:     ["▲/══\\\\ ", "\\\\\\\\⚡X\\\\\\\\", "d-==-b"],\n          right:    [" /══\\\\▲", "//X⚡//", "d-==-b"]\n        }\n      },\n      {\n        name: "🔥 PHANTOM DRIFT GT",\n        weaponName: "VULCAN CANNON",\n        bulletChar: "!",\n        bulletColor: "#ffe600",\n        flameColor: "#ff5500",\n        themeColor: "#ffe600",\n        sprites: {\n          straight: ["▌/──\\\\▐", "║[GT]║", "d════b"],\n          left:     ["▌/──\\\\ ", "\\\\\\\\GT\\\\\\\\", "d════b"],\n          right:    [" /──\\\\▐", "//GT//", "d════b"]\n        }\n      },\n      {\n        name: "🚨 POLICE ENFORCER",\n        weaponName: "MICRO ROCKETS",\n        bulletChar: "▲",\n        bulletColor: "#ff0055",\n        flameColor: "#0070f3",\n        themeColor: "#ff0055",\n        sprites: {\n          straight: ["!.[P].!", "║*911*║", "d----b"],\n          left:     ["!.[P]. ", "\\\\\\\\911\\\\\\\\", "d----b"],\n          right:    [" .[P].!", "//911//", "d----b"]\n        }\n      }\n    ];\n\n    const ENEMY_SPRITES = [\n      { lines: [" ┌─┐ ", "|{1}|", "\'-=-\'"], color: "#ff4444", hp: 1, name: "Coupe" },\n      { lines: [" ╔▲╗ ", "|{X}|", "d---b"], color: "#ff8800", hp: 1, name: "Rival" },\n      { lines: ["[═══]", "|TNT|", "[###]"], color: "#ff0055", hp: 1, name: "TNT Van" },\n      { lines: [" .T. ", "|TXI|", "\'-=-\'"], color: "#ffe600", hp: 1, name: "Taxi" },\n      { lines: ["[╬══╬]", "|WAR |", "|RIG |", "[####]"], color: "#b82e2e", hp: 2, name: "War Rig" },\n      { lines: [" /──\\\\ ", "|{M}|", "d---b"], color: "#aa00ff", hp: 1, name: "Muscle" }\n    ];\n\n    /* =========================================================================\n       3. GAME ENGINE CORE\n       ========================================================================= */\n    const canvas = document.getElementById(\'gameCanvas\');\n    const ctx = canvas.getContext(\'2d\');\n\n    let currentCarIdx = 0;\n    let gameState = "MENU"; // "MENU", "PLAYING", "GAMEOVER"\n    let score = 0;\n    let highScore = parseInt(localStorage.getItem(\'terminal_racing_highscore\') || \'0\', 10);\n    let enemiesDestroyed = 0;\n    let nearMissCount = 0;\n    let combo = 1;\n    let speed = 90;\n    let nitroGauge = 100;\n    let isBoosting = false;\n    let roadScrollOffset = 0;\n    let distance = 0;\n\n    // Player position\n    const LANES = [110, 240, 370];\n    let currentLane = 1;\n    let playerX = LANES[1];\n    let targetX = LANES[1];\n    let playerY = 510;\n    let steerDir = "straight"; // "left", "right", "straight"\n\n    // Entities\n    let bullets = [];\n    let enemies = [];\n    let particles = [];\n    let floatingTexts = [];\n    let skidMarks = [];\n    let stars = [];\n\n    // Keys\n    const keys = {\n      left: false,\n      right: false,\n      boost: false,\n      shoot: false\n    };\n\n    // Initialize Stars / Cyber Dust\n    for (let i = 0; i < 45; i++) {\n      stars.push({\n        x: Math.random() * canvas.width,\n        y: Math.random() * canvas.height,\n        speed: 1 + Math.random() * 3,\n        size: Math.random() > 0.8 ? 2 : 1\n      });\n    }\n\n    function updateCarPreview() {\n      const car = PLAYER_CARS[currentCarIdx];\n      document.getElementById(\'carPreviewName\').textContent = car.name;\n      document.getElementById(\'carPreviewArt\').textContent = car.sprites.straight.join(\'\\n\');\n      document.getElementById(\'carPreviewArt\').style.color = car.themeColor;\n      document.getElementById(\'carWeaponName\').textContent = "WEAPON: " + car.weaponName;\n      document.getElementById(\'carBulletType\').textContent = "FIRE: " + car.bulletChar;\n    }\n\n    function cycleCar() {\n      currentCarIdx = (currentCarIdx + 1) % PLAYER_CARS.length;\n      updateCarPreview();\n      sfx.switchCar();\n    }\n\n    function spawnBullet() {\n      const car = PLAYER_CARS[currentCarIdx];\n      // Left and right cannons\n      bullets.push({\n        x: playerX - 14,\n        y: playerY - 4,\n        char: car.bulletChar,\n        color: car.bulletColor,\n        vy: -14\n      });\n      bullets.push({\n        x: playerX + 14,\n        y: playerY - 4,\n        char: car.bulletChar,\n        color: car.bulletColor,\n        vy: -14\n      });\n      sfx.shoot();\n    }\n\n    function spawnEnemy() {\n      if (enemies.length >= 4) return;\n      const laneIdx = Math.floor(Math.random() * 3);\n      const enemyType = Math.floor(Math.random() * ENEMY_SPRITES.length);\n      const enemyData = ENEMY_SPRITES[enemyType];\n      \n      // Ensure lane isn\'t already occupied near the top\n      for (let e of enemies) {\n        if (Math.abs(e.x - LANES[laneIdx]) < 30 && e.y < 120) return;\n      }\n\n      enemies.push({\n        x: LANES[laneIdx],\n        y: -90,\n        type: enemyType,\n        sprite: enemyData.lines,\n        color: enemyData.color,\n        hp: enemyData.hp,\n        speed: 2.2 + Math.random() * 2.0,\n        passed: false\n      });\n    }\n\n    function createExplosion(x, y, color) {\n      sfx.explosion();\n      for (let i = 0; i < 22; i++) {\n        const angle = Math.random() * Math.PI * 2;\n        const speed = 2 + Math.random() * 5;\n        particles.push({\n          x: x,\n          y: y,\n          vx: Math.cos(angle) * speed,\n          vy: Math.sin(angle) * speed,\n          life: 1.0,\n          char: ["💥", "🔥", "⚡", "*", "•"][Math.floor(Math.random() * 5)],\n          color: color || "#ff0055"\n        });\n      }\n    }\n\n    function addFloatingText(x, y, text, color) {\n      floatingTexts.push({\n        x: x,\n        y: y,\n        text: text,\n        color: color || "#00f0ff",\n        life: 1.0\n      });\n    }\n\n    function startGame() {\n      sfx.init();\n      score = 0;\n      enemiesDestroyed = 0;\n      nearMissCount = 0;\n      combo = 1;\n      speed = 90;\n      nitroGauge = 100;\n      distance = 0;\n      bullets = [];\n      enemies = [];\n      particles = [];\n      floatingTexts = [];\n      skidMarks = [];\n      currentLane = 1;\n      playerX = LANES[1];\n      targetX = LANES[1];\n      gameState = "PLAYING";\n\n      document.getElementById(\'startScreen\').classList.add(\'hidden\');\n      document.getElementById(\'gameOverScreen\').classList.add(\'hidden\');\n    }\n\n    function gameOver() {\n      gameState = "GAMEOVER";\n      createExplosion(playerX, playerY, "#ff0055");\n      if (score > highScore) {\n        highScore = score;\n        localStorage.setItem(\'terminal_racing_highscore\', highScore.toString());\n      }\n      document.getElementById(\'finalScore\').textContent = score;\n      document.getElementById(\'finalHighScore\').textContent = highScore;\n      document.getElementById(\'finalKills\').textContent = enemiesDestroyed;\n      document.getElementById(\'finalPasses\').textContent = nearMissCount;\n      document.getElementById(\'gameOverScreen\').classList.remove(\'hidden\');\n    }\n\n    /* =========================================================================\n       4. INPUT HANDLERS\n       ========================================================================= */\n    window.addEventListener(\'keydown\', (e) => {\n      sfx.init();\n      if (e.key === "ArrowLeft" || e.key === "a" || e.key === "A") {\n        keys.left = true;\n        if (gameState === "PLAYING") {\n          currentLane = Math.max(0, currentLane - 1);\n          targetX = LANES[currentLane];\n        }\n      }\n      if (e.key === "ArrowRight" || e.key === "d" || e.key === "D") {\n        keys.right = true;\n        if (gameState === "PLAYING") {\n          currentLane = Math.min(2, currentLane + 1);\n          targetX = LANES[currentLane];\n        }\n      }\n      if (e.key === "ArrowUp" || e.key === "w" || e.key === "W" || e.key === "Shift") {\n        keys.boost = true;\n      }\n      if (e.key === " " || e.key === "j" || e.key === "J" || e.key === "f" || e.key === "F") {\n        e.preventDefault();\n        if (gameState === "MENU") {\n          startGame();\n        } else if (gameState === "PLAYING") {\n          spawnBullet();\n        }\n      }\n      if (e.key === "c" || e.key === "C") {\n        cycleCar();\n      }\n      if (e.key === "r" || e.key === "R") {\n        if (gameState === "GAMEOVER") {\n          startGame();\n        }\n      }\n    });\n\n    window.addEventListener(\'keyup\', (e) => {\n      if (e.key === "ArrowLeft" || e.key === "a" || e.key === "A") keys.left = false;\n      if (e.key === "ArrowRight" || e.key === "d" || e.key === "D") keys.right = false;\n      if (e.key === "ArrowUp" || e.key === "w" || e.key === "W" || e.key === "Shift") keys.boost = false;\n    });\n\n    // Mobile / Touch controls\n    document.getElementById(\'mLeftBtn\').addEventListener(\'touchstart\', (e) => {\n      e.preventDefault(); sfx.init();\n      if (gameState === "PLAYING") {\n        currentLane = Math.max(0, currentLane - 1);\n        targetX = LANES[currentLane];\n      }\n    });\n    document.getElementById(\'mRightBtn\').addEventListener(\'touchstart\', (e) => {\n      e.preventDefault(); sfx.init();\n      if (gameState === "PLAYING") {\n        currentLane = Math.min(2, currentLane + 1);\n        targetX = LANES[currentLane];\n      }\n    });\n    document.getElementById(\'mShootBtn\').addEventListener(\'touchstart\', (e) => {\n      e.preventDefault(); sfx.init();\n      if (gameState === "PLAYING") spawnBullet();\n      else if (gameState === "MENU") startGame();\n    });\n    document.getElementById(\'mBoostBtn\').addEventListener(\'touchstart\', (e) => {\n      e.preventDefault(); sfx.init();\n      keys.boost = true;\n    });\n    document.getElementById(\'mBoostBtn\').addEventListener(\'touchend\', (e) => {\n      e.preventDefault();\n      keys.boost = false;\n    });\n\n    // UI Buttons\n    document.getElementById(\'startPlayBtn\').addEventListener(\'click\', startGame);\n    document.getElementById(\'restartBtn\').addEventListener(\'click\', startGame);\n    document.getElementById(\'changeCarBtn\').addEventListener(\'click\', cycleCar);\n\n    const toggleAudioBtn = document.getElementById(\'toggleAudioBtn\');\n    toggleAudioBtn.addEventListener(\'click\', () => {\n      sfx.init();\n      sfx.enabled = !sfx.enabled;\n      toggleAudioBtn.textContent = sfx.enabled ? "🔊 AUDIO: ON" : "🔇 AUDIO: OFF";\n    });\n\n    const toggleCrtBtn = document.getElementById(\'toggleCrtBtn\');\n    toggleCrtBtn.addEventListener(\'click\', () => {\n      const crt = document.getElementById(\'crtOverlay\');\n      if (crt.style.opacity === "0") {\n        crt.style.opacity = "0.65";\n        toggleCrtBtn.textContent = "📺 CRT: ON";\n      } else {\n        crt.style.opacity = "0";\n        toggleCrtBtn.textContent = "📺 CRT: OFF";\n      }\n    });\n\n    /* =========================================================================\n       5. MAIN UPDATE & RENDER LOOP\n       ========================================================================= */\n    let lastSpawnTime = 0;\n\n    function update(dt) {\n      if (gameState !== "PLAYING") return;\n\n      // Handle Nitro Boost\n      if (keys.boost && nitroGauge > 0) {\n        speed = Math.min(220, speed + 120 * dt);\n        nitroGauge = Math.max(0, nitroGauge - 35 * dt);\n        isBoosting = true;\n        if (Math.random() < 0.3) sfx.nitro();\n      } else {\n        speed = Math.max(90, speed - 80 * dt);\n        nitroGauge = Math.min(100, nitroGauge + 15 * dt);\n        isBoosting = false;\n      }\n\n      distance += (speed * dt) * 0.1;\n      score += Math.floor(speed * 0.05 * combo);\n      roadScrollOffset += (speed * 0.1);\n\n      // Smooth horizontal steering\n      const dx = targetX - playerX;\n      playerX += dx * 0.22;\n\n      if (dx < -3) steerDir = "left";\n      else if (dx > 3) steerDir = "right";\n      else steerDir = "straight";\n\n      // Nitro exhaust flames particles\n      const car = PLAYER_CARS[currentCarIdx];\n      if (isBoosting || Math.random() < 0.4) {\n        particles.push({\n          x: playerX + (Math.random() * 16 - 8),\n          y: playerY + 28,\n          vx: (Math.random() - 0.5) * 2,\n          vy: 3 + Math.random() * 4,\n          life: 0.5,\n          char: isBoosting ? "🔥" : "•",\n          color: isBoosting ? car.flameColor : "#00f0ff"\n        });\n      }\n\n      // Spawn enemies periodically\n      const now = performance.now();\n      if (now - lastSpawnTime > Math.max(700, 1600 - (speed * 4))) {\n        spawnEnemy();\n        lastSpawnTime = now;\n      }\n\n      // Update bullets\n      for (let i = bullets.length - 1; i >= 0; i--) {\n        const b = bullets[i];\n        b.y += b.vy;\n        if (b.y < -20) {\n          bullets.splice(i, 1);\n        }\n      }\n\n      // Update enemies & collision\n      for (let i = enemies.length - 1; i >= 0; i--) {\n        const e = enemies[i];\n        e.y += e.speed + (speed * 0.04);\n\n        // Near-miss check\n        if (!e.passed && e.y > playerY - 20 && e.y < playerY + 30) {\n          if (Math.abs(e.x - playerX) < 70 && Math.abs(e.x - playerX) > 30) {\n            e.passed = true;\n            nearMissCount++;\n            combo++;\n            score += 250 * combo;\n            addFloatingText(e.x, e.y, `NEAR MISS! +${250 * combo}`, "#00ff66");\n            sfx.nearMiss();\n          }\n        }\n\n        // Bullet vs Enemy collision\n        for (let j = bullets.length - 1; j >= 0; j--) {\n          const b = bullets[j];\n          if (Math.abs(b.x - e.x) < 28 && Math.abs(b.y - e.y) < 32) {\n            bullets.splice(j, 1);\n            e.hp--;\n            if (e.hp <= 0) {\n              createExplosion(e.x, e.y, e.color);\n              enemiesDestroyed++;\n              score += 500 * combo;\n              addFloatingText(e.x, e.y, `+${500 * combo}`, "#ffe600");\n              enemies.splice(i, 1);\n              break;\n            } else {\n              addFloatingText(e.x, e.y, "HIT!", "#ff0055");\n            }\n          }\n        }\n\n        // Player vs Enemy crash\n        if (Math.abs(e.x - playerX) < 34 && Math.abs(e.y - playerY) < 38) {\n          gameOver();\n          return;\n        }\n\n        // Remove offscreen enemies\n        if (e.y > canvas.height + 60) {\n          enemies.splice(i, 1);\n        }\n      }\n\n      // Update particles\n      for (let i = particles.length - 1; i >= 0; i--) {\n        const p = particles[i];\n        p.x += p.vx;\n        p.y += p.vy;\n        p.life -= dt * 2.0;\n        if (p.life <= 0) particles.splice(i, 1);\n      }\n\n      // Update floating texts\n      for (let i = floatingTexts.length - 1; i >= 0; i--) {\n        const t = floatingTexts[i];\n        t.y -= 30 * dt;\n        t.life -= dt * 1.5;\n        if (t.life <= 0) floatingTexts.splice(i, 1);\n      }\n    }\n\n    function render() {\n      ctx.fillStyle = "#05070a";\n      ctx.fillRect(0, 0, canvas.width, canvas.height);\n\n      // Render starfield / speed lines\n      ctx.fillStyle = "#1e293b";\n      for (let star of stars) {\n        star.y += star.speed + (speed * 0.02);\n        if (star.y > canvas.height) {\n          star.y = 0;\n          star.x = Math.random() * canvas.width;\n        }\n        ctx.fillRect(star.x, star.y, star.size, star.size * (isBoosting ? 6 : 1));\n      }\n\n      // Road Area\n      const roadLeft = 50;\n      const roadRight = 430;\n      const roadWidth = roadRight - roadLeft;\n\n      // Asphalt base\n      ctx.fillStyle = "#0a0e17";\n      ctx.fillRect(roadLeft, 0, roadWidth, canvas.height);\n\n      // Neon road borders\n      ctx.strokeStyle = "#00f0ff";\n      ctx.lineWidth = 4;\n      ctx.shadowColor = "#00f0ff";\n      ctx.shadowBlur = 10;\n      ctx.beginPath();\n      ctx.moveTo(roadLeft, 0);\n      ctx.lineTo(roadLeft, canvas.height);\n      ctx.moveTo(roadRight, 0);\n      ctx.lineTo(roadRight, canvas.height);\n      ctx.stroke();\n\n      // Dashed lane divider lines\n      ctx.strokeStyle = "rgba(0, 240, 255, 0.4)";\n      ctx.lineWidth = 2;\n      ctx.shadowBlur = 4;\n      const lane1X = roadLeft + roadWidth / 3;\n      const lane2X = roadLeft + (roadWidth * 2) / 3;\n      const dashLen = 25;\n      const gapLen = 20;\n      const offset = roadScrollOffset % (dashLen + gapLen);\n\n      for (let y = -dashLen + offset; y < canvas.height; y += dashLen + gapLen) {\n        ctx.beginPath();\n        ctx.moveTo(lane1X, y);\n        ctx.lineTo(lane1X, y + dashLen);\n        ctx.moveTo(lane2X, y);\n        ctx.lineTo(lane2X, y + dashLen);\n        ctx.stroke();\n      }\n      ctx.shadowBlur = 0; // reset glow\n\n      // Headlight Beams from Player Car\n      const grad = ctx.createLinearGradient(0, playerY, 0, playerY - 180);\n      grad.addColorStop(0, "rgba(0, 240, 255, 0.2)");\n      grad.addColorStop(1, "rgba(0, 240, 255, 0.0)");\n      ctx.fillStyle = grad;\n      ctx.beginPath();\n      ctx.moveTo(playerX - 20, playerY);\n      ctx.lineTo(playerX - 55, playerY - 180);\n      ctx.lineTo(playerX + 55, playerY - 180);\n      ctx.lineTo(playerX + 20, playerY);\n      ctx.closePath();\n      ctx.fill();\n\n      // Render Enemies\n      ctx.font = \'16px "Share Tech Mono", monospace\';\n      ctx.textAlign = \'center\';\n      for (let e of enemies) {\n        ctx.fillStyle = e.color;\n        ctx.shadowColor = e.color;\n        ctx.shadowBlur = 8;\n        const lines = e.sprite;\n        for (let l = 0; l < lines.length; l++) {\n          ctx.fillText(lines[l], e.x, e.y + (l * 16));\n        }\n      }\n      ctx.shadowBlur = 0;\n\n      // Render Bullets\n      for (let b of bullets) {\n        ctx.fillStyle = b.color;\n        ctx.shadowColor = b.color;\n        ctx.shadowBlur = 10;\n        ctx.font = \'bold 18px "Share Tech Mono", monospace\';\n        ctx.fillText(b.char, b.x, b.y);\n      }\n      ctx.shadowBlur = 0;\n\n      // Render Player Car\n      const currentCar = PLAYER_CARS[currentCarIdx];\n      const carLines = currentCar.sprites[steerDir] || currentCar.sprites.straight;\n      ctx.fillStyle = currentCar.themeColor;\n      ctx.shadowColor = currentCar.themeColor;\n      ctx.shadowBlur = 12;\n      ctx.font = \'bold 18px "Share Tech Mono", monospace\';\n      for (let l = 0; l < carLines.length; l++) {\n        ctx.fillText(carLines[l], playerX, playerY + (l * 17));\n      }\n      ctx.shadowBlur = 0;\n\n      // Render Particles\n      for (let p of particles) {\n        ctx.fillStyle = p.color;\n        ctx.font = \'14px monospace\';\n        ctx.fillText(p.char, p.x, p.y);\n      }\n\n      // Render Floating Texts\n      for (let t of floatingTexts) {\n        ctx.fillStyle = t.color;\n        ctx.font = \'bold 15px "Orbitron", sans-serif\';\n        ctx.shadowColor = t.color;\n        ctx.shadowBlur = 8;\n        ctx.fillText(t.text, t.x, t.y);\n      }\n      ctx.shadowBlur = 0;\n\n      // Render Top HUD Overlay inside Canvas\n      ctx.fillStyle = "rgba(10, 14, 23, 0.85)";\n      ctx.fillRect(0, 0, canvas.width, 42);\n      ctx.strokeStyle = "rgba(0, 240, 255, 0.3)";\n      ctx.beginPath();\n      ctx.moveTo(0, 42);\n      ctx.lineTo(canvas.width, 42);\n      ctx.stroke();\n\n      ctx.font = \'13px "Orbitron", sans-serif\';\n      ctx.textAlign = \'left\';\n      ctx.fillStyle = \'#00f0ff\';\n      ctx.fillText(`SCORE: ${score}`, 14, 26);\n\n      ctx.textAlign = \'center\';\n      ctx.fillStyle = isBoosting ? \'#ff0055\' : \'#ffe600\';\n      ctx.fillText(`${Math.round(speed)} MPH`, canvas.width / 2, 26);\n\n      ctx.textAlign = \'right\';\n      ctx.fillStyle = \'#00ff66\';\n      ctx.fillText(`COMBO: x${combo}`, canvas.width - 14, 26);\n\n      // Nitro gauge line\n      ctx.fillStyle = \'#1e293b\';\n      ctx.fillRect(0, 41, canvas.width, 3);\n      ctx.fillStyle = isBoosting ? \'#ff0055\' : \'#00f0ff\';\n      ctx.fillRect(0, 41, (canvas.width * (nitroGauge / 100)), 3);\n    }\n\n    let prevTime = performance.now();\n    function gameLoop(time) {\n      const dt = Math.min((time - prevTime) / 1000, 0.1);\n      prevTime = time;\n\n      update(dt);\n      render();\n\n      requestAnimationFrame(gameLoop);\n    }\n\n    updateCarPreview();\n    requestAnimationFrame(gameLoop);\n  </script>\n</body>\n</html>\n'

def app(environ, start_response):
    body = HTML_CONTENT.encode('utf-8')
    start_response('200 OK', [
        ('Content-type', 'text/html; charset=utf-8'),
        ('Content-Length', str(len(body))),
        ('Cache-Control', 'no-cache, no-store, must-revalidate')
    ])
    return [body]

class handler(BaseHTTPRequestHandler):
    def do_GET(self):
        body = HTML_CONTENT.encode('utf-8')
        self.send_response(200)
        self.send_header('Content-type', 'text/html; charset=utf-8')
        self.send_header('Content-Length', str(len(body)))
        self.send_header('Cache-Control', 'no-cache, no-store, must-revalidate')
        self.end_headers()
        self.wfile.write(body)
